//! The elevated PowerShell, generated by pure functions so every byte is
//! unit tested. Nothing here runs anything.
//!
//! Quoting: every value lands in a single-quoted PowerShell string, where
//! nothing is expanded. Inside one, PowerShell ends the string at ' and at
//! the typographic quotes U+2018, U+2019, U+201A, U+201B; each is doubled.
//! Comment lines carry aliases too, so control characters there become
//! spaces (a newline would end the comment and start a command).
//!
//! Each adapter is changed in its own try/catch: a renamed or removed
//! adapter is reported and the others still change. Any failure ends the
//! script with exit 1, and the restore script then keeps the backup.

use std::path::Path;

use super::{FamilyDns, InterfaceDns, SIEVE_V4, SIEVE_V6};

/// Characters that end a single-quoted PowerShell string.
const PS_QUOTES: [char; 5] = ['\'', '\u{2018}', '\u{2019}', '\u{201A}', '\u{201B}'];

/// `s` as a single-quoted PowerShell literal.
pub fn ps_quote(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('\'');
    for c in s.chars() {
        if PS_QUOTES.contains(&c) {
            out.push(c);
        }
        out.push(c);
    }
    out.push('\'');
    out
}

/// `s` safe inside a `#` comment line.
fn comment(s: &str) -> String {
    s.chars().map(|c| if c.is_control() { ' ' } else { c }).collect()
}

/// How a command names the adapter: by alias (quoted), or by index when the
/// alias holds control characters (a literal newline would split the line,
/// even though it is harmless inside the quotes).
fn target(i: &InterfaceDns) -> String {
    if i.alias.chars().any(char::is_control) {
        format!("-InterfaceIndex {}", i.index)
    } else {
        format!("-InterfaceAlias {}", ps_quote(&i.alias))
    }
}

fn list(servers: &[String]) -> String {
    let items: Vec<String> = servers.iter().map(|s| ps_quote(s)).collect();
    format!("@({})", items.join(","))
}

fn describe(f: &FamilyDns) -> String {
    if f.dhcp || f.servers.is_empty() { "from DHCP".to_owned() } else { format!("set by hand {}", f.servers.join(", ")) }
}

const HEADER_STOP: &str = "$ErrorActionPreference = 'Stop'\n$failed = @()\n";

/// Runs `body` for one adapter; on error records the alias and goes on.
fn guarded(alias: &str, body: &[String]) -> String {
    let mut s = String::from("try {\n");
    for line in body {
        s.push_str("    ");
        s.push_str(line);
        s.push('\n');
    }
    s.push_str(&format!(
        "}} catch {{\n    $failed += {q}\n    Write-Warning (\"DNS of \" + {q} + \" was not changed: \" + $_.Exception.Message)\n}}\n",
        q = ps_quote(alias)
    ));
    s
}

/// Points every adapter in `interfaces` at Sieve: IPv4 DNS 127.0.0.1, IPv6 DNS ::1.
/// `backup` is only named in the header, so a reader knows where the old values are.
pub fn point_script(interfaces: &[InterfaceDns], backup: &Path) -> String {
    let mut s = String::from("# Sieve: point Windows DNS at Sieve's DNS filter (127.0.0.1 and ::1).\n");
    s.push_str(&format!("# The DNS before this change is saved in {}\n", comment(&backup.display().to_string())));
    s.push_str("# and restore-dns.ps1 next to it puts it back.\n");
    s.push_str(HEADER_STOP);
    let sieve = list(&[SIEVE_V4.to_string(), SIEVE_V6.to_string()]);
    for i in interfaces {
        s.push_str(&format!(
            "# {} (index {}): IPv4 was {}; IPv6 was {}\n",
            comment(&i.alias),
            i.index,
            describe(&i.v4),
            describe(&i.v6)
        ));
        s.push_str(&guarded(&comment(&i.alias), &[format!("Set-DnsClientServerAddress {} -ServerAddresses {sieve}", target(i))]));
    }
    s.push_str(FLUSH);
    s.push_str("if ($failed.Count -gt 0) { exit 1 }\nexit 0\n");
    s
}

/// Drop cached answers so the change shows at once; a failure here is not a failed change.
const FLUSH: &str = "Clear-DnsClientCache -ErrorAction SilentlyContinue\n";

/// The commands that put one adapter back exactly. DHCP families come back
/// through -ResetServerAddresses (which resets both families), so it runs
/// first and a hand-set family is set again after it.
pub fn restore_commands(i: &InterfaceDns) -> Vec<String> {
    let t = target(i);
    let hand = |f: &FamilyDns| !f.dhcp && !f.servers.is_empty();
    let mut out = Vec::new();
    if !(hand(&i.v4) && hand(&i.v6)) {
        out.push(format!("Set-DnsClientServerAddress {t} -ResetServerAddresses"));
    }
    let set: Vec<String> = [&i.v4, &i.v6].into_iter().filter(|f| hand(f)).flat_map(|f| f.servers.clone()).collect();
    if !set.is_empty() {
        out.push(format!("Set-DnsClientServerAddress {t} -ServerAddresses {}", list(&set)));
    }
    out
}

/// Asks for administrator rights when started by hand (right-click, Run
/// with PowerShell); when Sieve starts it elevated this is a no-op.
const SELF_ELEVATE: &str = "\
$admin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $admin) {
    Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', ('\"{0}\"' -f $PSCommandPath))
    exit
}
";

/// Restores every adapter in the backup, then deletes the backup (only when
/// every adapter came back, so a failed restore can be run again).
pub fn restore_script(interfaces: &[InterfaceDns], backup: &Path) -> String {
    let mut s = String::from("# Sieve: restore Windows DNS to what it was before Sieve pointed it at its DNS filter.\n");
    s.push_str("# Works without Sieve: right-click this file, Run with PowerShell, and accept the Windows prompt.\n");
    s.push_str(&format!("# Values from the backup {}\n", comment(&backup.display().to_string())));
    s.push_str(SELF_ELEVATE);
    s.push_str(HEADER_STOP);
    for i in interfaces {
        s.push_str(&format!(
            "# {} (index {}): IPv4 {}; IPv6 {}\n",
            comment(&i.alias),
            i.index,
            describe(&i.v4),
            describe(&i.v6)
        ));
        s.push_str(&guarded(&comment(&i.alias), &restore_commands(i)));
    }
    s.push_str(FLUSH);
    s.push_str("if ($failed.Count -gt 0) { exit 1 }\n");
    s.push_str(&format!(
        "Remove-Item -LiteralPath {} -Force -ErrorAction SilentlyContinue\n",
        ps_quote(&backup.display().to_string())
    ));
    s.push_str("exit 0\n");
    s
}

#[cfg(test)]
mod tests {
    use super::super::tests::{fam, sample};
    use super::*;
    use std::path::PathBuf;

    fn backup_path() -> PathBuf {
        PathBuf::from(r"C:\Users\Sam O'Neil\AppData\Roaming\app.sieve.desktop\system-dns\backup.json")
    }

    #[test]
    fn quoting_doubles_every_quote_powershell_honours() {
        assert_eq!(ps_quote("Wi-Fi"), "'Wi-Fi'");
        assert_eq!(ps_quote("Bob's LAN"), "'Bob''s LAN'");
        assert_eq!(ps_quote("a\u{2019}b\u{2018}c"), "'a\u{2019}\u{2019}b\u{2018}\u{2018}c'");
        assert_eq!(ps_quote("x\u{201A}\u{201B}"), "'x\u{201A}\u{201A}\u{201B}\u{201B}'");
        // Nothing else is special inside single quotes: $, backtick, double quote stay.
        assert_eq!(ps_quote("$(rm -r C:\\) `\" ;"), "'$(rm -r C:\\) `\" ;'");
    }

    /// Reads a single-quoted PowerShell literal the way PowerShell does and
    /// returns it with the rest of the line, to prove quoting round-trips.
    fn unquote(s: &str) -> (String, &str) {
        let mut chars = s.char_indices().peekable();
        assert_eq!(chars.next().map(|c| c.1), Some('\''));
        let mut out = String::new();
        while let Some((i, c)) = chars.next() {
            if PS_QUOTES.contains(&c) {
                if chars.peek().map(|n| n.1) == Some(c) {
                    chars.next();
                    out.push(c);
                } else {
                    return (out, &s[i + c.len_utf8()..]);
                }
            } else {
                out.push(c);
            }
        }
        panic!("unterminated literal: {s}");
    }

    #[test]
    fn hostile_aliases_stay_one_argument() {
        for alias in ["Bob's LAN", "x'; Remove-Item C:\\ -Recurse; '", "a\u{2019}; calc; \u{2018}", "tab\there", "new\nline"] {
            let q = ps_quote(alias);
            let (back, rest) = unquote(&q);
            assert_eq!(back, alias);
            assert_eq!(rest, "", "{alias:?} ended its literal early");
        }
    }

    #[test]
    fn point_sets_both_families_on_every_adapter() {
        let s = point_script(&sample(), &backup_path());
        assert!(s.contains("Set-DnsClientServerAddress -InterfaceAlias 'Wi-Fi' -ServerAddresses @('127.0.0.1','::1')"));
        assert!(s.contains("Set-DnsClientServerAddress -InterfaceAlias 'Ethernet 2' -ServerAddresses @('127.0.0.1','::1')"));
        assert_eq!(s.matches("Set-DnsClientServerAddress").count(), 2);
        assert!(s.contains("# Wi-Fi (index 12): IPv4 was from DHCP; IPv6 was from DHCP"));
        assert!(s.contains("# Ethernet 2 (index 7): IPv4 was set by hand 198.51.100.53, 203.0.113.53; IPv6 was from DHCP"));
        assert!(s.contains("Clear-DnsClientCache"));
        assert!(s.ends_with("if ($failed.Count -gt 0) { exit 1 }\nexit 0\n"));
        // The point script never deletes anything.
        assert!(!s.contains("Remove-Item"));
    }

    #[test]
    fn restore_resets_dhcp_and_sets_hand_set_servers_back() {
        let [wifi, eth] = <[InterfaceDns; 2]>::try_from(sample()).expect("two");
        assert_eq!(restore_commands(&wifi), vec!["Set-DnsClientServerAddress -InterfaceAlias 'Wi-Fi' -ResetServerAddresses"]);
        assert_eq!(
            restore_commands(&eth),
            vec![
                "Set-DnsClientServerAddress -InterfaceAlias 'Ethernet 2' -ResetServerAddresses",
                "Set-DnsClientServerAddress -InterfaceAlias 'Ethernet 2' -ServerAddresses @('198.51.100.53','203.0.113.53')",
            ]
        );
        // Both families set by hand: no reset, one call with every address.
        let both = InterfaceDns {
            alias: "Lab".into(),
            index: 3,
            v4: fam(&["192.0.2.1"], false),
            v6: fam(&["2001:db8::1", "2001:db8::2"], false),
        };
        assert_eq!(
            restore_commands(&both),
            vec!["Set-DnsClientServerAddress -InterfaceAlias 'Lab' -ServerAddresses @('192.0.2.1','2001:db8::1','2001:db8::2')"]
        );
        // Only IPv6 by hand: reset, then IPv6 again.
        let v6 = InterfaceDns { alias: "V6".into(), index: 4, v4: fam(&["192.0.2.9"], true), v6: fam(&["2001:db8::9"], false) };
        assert_eq!(
            restore_commands(&v6),
            vec![
                "Set-DnsClientServerAddress -InterfaceAlias 'V6' -ResetServerAddresses",
                "Set-DnsClientServerAddress -InterfaceAlias 'V6' -ServerAddresses @('2001:db8::9')",
            ]
        );
        // A "hand-set" family with no servers is not a thing: it restores as DHCP.
        let odd = InterfaceDns { alias: "Odd".into(), index: 5, v4: fam(&[], false), v6: fam(&[], false) };
        assert_eq!(restore_commands(&odd), vec!["Set-DnsClientServerAddress -InterfaceAlias 'Odd' -ResetServerAddresses"]);
    }

    #[test]
    fn restore_script_elevates_itself_restores_and_deletes_the_backup_last() {
        let s = restore_script(&sample(), &backup_path());
        assert!(s.contains("-Verb RunAs"), "runs by hand too");
        let reset = s.find("-InterfaceAlias 'Wi-Fi' -ResetServerAddresses").expect("wifi reset");
        let fail = s.find("if ($failed.Count -gt 0) { exit 1 }").expect("failure exit");
        let remove = s
            .find(r"Remove-Item -LiteralPath 'C:\Users\Sam O''Neil\AppData\Roaming\app.sieve.desktop\system-dns\backup.json'")
            .expect("backup removal, path quoted");
        assert!(reset < fail && fail < remove, "the backup goes only after every adapter came back");
        assert!(s.ends_with("exit 0\n"));
    }

    #[test]
    fn a_control_character_in_an_alias_never_reaches_a_line_start_and_the_index_is_used() {
        let evil = InterfaceDns { alias: "x\nRemove-Item C:\\ -Recurse".into(), index: 41, v4: fam(&[], true), v6: fam(&[], true) };
        for s in [point_script(std::slice::from_ref(&evil), &backup_path()), restore_script(std::slice::from_ref(&evil), &backup_path())] {
            assert!(
                !s.lines().any(|l| l.trim_start().starts_with("Remove-Item C:")),
                "the alias text never starts a line:\n{s}"
            );
            assert!(s.contains("Set-DnsClientServerAddress -InterfaceIndex 41 "), "{s}");
            assert!(!s.contains("-InterfaceAlias"), "{s}");
        }
    }

    /// The text the report shows for the two sample adapters.
    #[test]
    fn sample_scripts_print() {
        println!("{}", point_script(&sample(), &backup_path()));
        println!("{}", restore_script(&sample(), &backup_path()));
    }
}
